import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Build query - sort column is validated against schema
        String query = buildReportQuery(reportType, dateRange, department, sortCol);
        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || type.equals("inventory")
                || type.equals("personnel") || type.equals("audit"));
    }

    private String buildReportQuery(String type, String range, String dept, String sort) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM report_").append(type).append("_view");

        boolean hasWhere = false;
        if (range != null) {
            String[] parts = range.split("_");
            sb.append(" WHERE created_at BETWEEN '").append(parts[0])
              .append("' AND '").append(parts[1]).append("'");
            hasWhere = true;
        }

        if (dept != null && !dept.isEmpty()) {
            sb.append(hasWhere ? " AND " : " WHERE ");
            sb.append("department = '").append(dept).append("'");
        }

        if (sort != null && !sort.isEmpty()) {
            sb.append(" ORDER BY ").append(sort);
        }

        return sb.toString();
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder json = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) json.append(",");
            json.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) json.append(",");
                json.append("\"").append(meta.getColumnName(i)).append("\":");
                String val = rs.getString(i);
                json.append(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
            }
            json.append("}");
            first = false;
        }
        json.append("]");
        return json.toString();
    }
}
